{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "금연 캠페인을 하는 시민단체가 서울시 지원을 받을 수 있는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "금연 캠페인을 하는 시민단체는 금연환경 조성 및 간접흡연 피해방지를 위한 홍보를 하는 단체에 해당할 수 있으므로, 시장이 지원할 수 있는 대상에 포함될 수 있다. 조례 제4조제3항은 시장이 금연환경조성 및 간접흡연 피해방지를 위한 조사·연구·홍보를 하는 법인 또는 단체를 지원할 수 있다고 정하고 있다. 또한 제9조제1항은 시장이 민간단체 및 각급 학교에서 실시하는 금연교육 및 홍보를 지원할 수 있다고 정하고 있다. 다만 실제 지원 여부는 시장의 인정 등 구체적 판단에 따른다.",
          "b_ids": "금연:제4조제3항, 금연:제9조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
